#include <LiquidCrystal.h>
#include <math.h>

// =====================================================
// 1. PIN CONFIGURATION
// =====================================================

LiquidCrystal lcd(12, 11, 5, 4, 3, 2);

const int LM35_PIN  = A0;
const int HEATER_PIN = 9;
const int FAN_PIN    = 10;

// =====================================================
// 2. TEMPERATURE SETTINGS
// =====================================================

const double SETPOINT = 25.0;

// نطاق السماح حول درجة الحرارة المطلوبة
const double STOP_BAND = 0.15;

// حدود إعادة التشغيل لمنع التبديل المتكرر
const double HEATER_RESTART_TEMP = 24.5;
const double FAN_RESTART_TEMP    = 25.5;

// =====================================================
// 3. PID PARAMETERS
// =====================================================

double Kp = 35.0;
double Ki = 0.20;
double Kd = 3.0;

double integral = 0.0;
double previousError = 0.0;

// =====================================================
// 4. MOTOR SETTINGS
// =====================================================

// أقل PWM مبدئي للتشغيل المستقر.
// يجب اختباره حسب نوع الموتور المستخدم.
const int MIN_PWM = 120;
const int MAX_PWM = 255;

// أقل مدة بين تغيير حالة الموتور
const unsigned long MIN_SWITCH_INTERVAL = 3000;

// =====================================================
// 5. THERMAL SIMULATION MODEL
// =====================================================

// معاملات تقريبية للمحاكاة وليست خواصًا حقيقية لصوبة.
const double HEATING_RATE = 0.12;
const double COOLING_RATE = 0.15;
const double PASSIVE_LOSS = 0.015;

double initialTemperature = 25.0;
double simulatedTemperature = 25.0;

// =====================================================
// 6. CONTROL VARIABLES
// =====================================================

int heaterPWM = 0;
int fanPWM = 0;

bool heaterEnabled = false;
bool fanEnabled = false;

unsigned long lastControlTime = 0;
unsigned long lastSwitchTime = 0;
unsigned long lastLCDTime = 0;

// =====================================================
// 7. READ LM35
// =====================================================

double readLM35() {
  int sensorValue = analogRead(LM35_PIN);

  double voltage = sensorValue * (5.0 / 1023.0);

  // LM35: 10 mV لكل درجة مئوية
  double temperature = voltage * 100.0;

  return temperature;
}

// =====================================================
// 8. SET MOTOR OUTPUT
// =====================================================

void applyOutputs() {
  analogWrite(HEATER_PIN, heaterPWM);
  analogWrite(FAN_PIN, fanPWM);
}

// =====================================================
// 9. MOTOR CONTROL WITH MINIMUM PWM
// =====================================================

int calculateMotorPWM(double output) {
  int pwm = (int)constrain(output, 0.0, 255.0);

  // الموتور إما يعمل بقدرة كافية أو يفصل.
  // لا نتركه يعمل بقيمة PWM ضعيفة جدًا.
  if (pwm > 0 && pwm < MIN_PWM) {
    pwm = MIN_PWM;
  }

  return pwm;
}

// =====================================================
// 10. PID CONTROLLER
// =====================================================

void updatePID(double dt) {
  double error = SETPOINT - simulatedTemperature;

  // عند الوصول إلى الهدف، نوقف الموتورين.
  // ونستخدم حدود إعادة التشغيل لتجنب التبديل المتكرر.
  if (simulatedTemperature >= 25.0 - STOP_BAND &&
      simulatedTemperature <= 25.0 + STOP_BAND) {

    heaterPWM = 0;
    fanPWM = 0;

    heaterEnabled = false;
    fanEnabled = false;

    integral = 0.0;
    previousError = error;

    applyOutputs();
    return;
  }

  // حساب PID
  integral += error * dt;
  integral = constrain(integral, -50.0, 50.0);

  double derivative = 0.0;

  if (dt > 0.0) {
    derivative = (error - previousError) / dt;
  }

  double pidOutput =
      (Kp * error) +
      (Ki * integral) +
      (Kd * derivative);

  previousError = error;

  // -----------------------------------------------
  // HEATING MODE
  // -----------------------------------------------

  if (error > 0.0) {

    fanPWM = 0;
    fanEnabled = false;

    // لا نشغل السخان إلا إذا وصلت الحرارة لحد إعادة التشغيل
    if (simulatedTemperature <= HEATER_RESTART_TEMP) {
      heaterEnabled = true;
    }

    if (heaterEnabled) {
      heaterPWM = calculateMotorPWM(fabs(pidOutput));
    } else {
      heaterPWM = 0;
    }
  }

  // -----------------------------------------------
  // COOLING MODE
  // -----------------------------------------------

  else {

    heaterPWM = 0;
    heaterEnabled = false;

    // لا نشغل المروحة إلا إذا وصلت الحرارة لحد إعادة التشغيل
    if (simulatedTemperature >= FAN_RESTART_TEMP) {
      fanEnabled = true;
    }

    if (fanEnabled) {
      fanPWM = calculateMotorPWM(fabs(pidOutput));
    } else {
      fanPWM = 0;
    }
  }

  applyOutputs();
}

// =====================================================
// 11. SIMULATE GREENHOUSE TEMPERATURE
// =====================================================

void updateTemperatureModel(double dt) {

  double heatingEffect =
      HEATING_RATE * ((double)heaterPWM / 255.0);

  double coolingEffect =
      COOLING_RATE * ((double)fanPWM / 255.0);

  double passiveEffect =
      PASSIVE_LOSS * (simulatedTemperature - initialTemperature);

  simulatedTemperature +=
      (heatingEffect - coolingEffect - passiveEffect) * dt;

  simulatedTemperature =
      constrain(simulatedTemperature, -20.0, 100.0);
}

// =====================================================
// 12. LCD DISPLAY
// =====================================================

void updateLCD() {

  lcd.setCursor(0, 0);

  lcd.print("Temp:");
  lcd.print(simulatedTemperature, 1);
  lcd.print((char)223);
  lcd.print("C   ");

  lcd.setCursor(0, 1);

  if (heaterPWM > 0) {
    lcd.print("HEAT PWM:");
    lcd.print(heaterPWM);
    lcd.print("   ");
  }
  else if (fanPWM > 0) {
    lcd.print("FAN PWM:");
    lcd.print(fanPWM);
    lcd.print("     ");
  }
  else {
    lcd.print("TARGET REACHED ");
  }
}

// =====================================================
// 13. SETUP
// =====================================================

void setup() {

  pinMode(HEATER_PIN, OUTPUT);
  pinMode(FAN_PIN, OUTPUT);

  analogWrite(HEATER_PIN, 0);
  analogWrite(FAN_PIN, 0);

  lcd.begin(16, 2);

  lcd.setCursor(0, 0);
  lcd.print("SMART GREENHOUSE");

  lcd.setCursor(0, 1);
  lcd.print("PID CONTROLLER");

  delay(2000);

  // قراءة LM35 عند بداية المحاكاة فقط
  initialTemperature = readLM35();

  // استخدام درجة الحساس كدرجة بداية للنموذج
  simulatedTemperature = initialTemperature;

  previousError = SETPOINT - simulatedTemperature;

  lastControlTime = millis();
  lastSwitchTime = millis();

  lcd.clear();
}

// =====================================================
// 14. MAIN LOOP
// =====================================================

void loop() {

  unsigned long currentTime = millis();

  // تحديث التحكم كل 100 ms
  if (currentTime - lastControlTime >= 100) {

    double dt =
        (currentTime - lastControlTime) / 1000.0;

    lastControlTime = currentTime;

    // تحديث نموذج درجة الحرارة
    updateTemperatureModel(dt);

    // حساب PID وتحديد قدرة الموتورين
    updatePID(dt);
  }

  // تحديث الشاشة كل 300 ms
  if (currentTime - lastLCDTime >= 300) {

    lastLCDTime = currentTime;

    updateLCD();
  }
}
